%[text] # Time trace example
%[text] 
signal_design_matrix = SignalTool2.generateSignalDesignMatrixFromTraceProperties(...
  RandomSeed = 123, ...
  FInitialValue = 0, ...
  XInitialFlatLength = 5, ...
  XInitialTransitionLength = 5, ...
  NumTransitions = 10, ...
  TransitionXRange = [10 30], ...
  FlatXRange = [60 120], ...
  FRange = [-10 30], ...
  XFinalTransitionLength = 10, ...
  XFinalFlatLength = 10, ...
  FFinalValue = 0 );

data_table = SignalTool2.getXYVectorsFromSignalDesignMatrix(signal_design_matrix);

fig = figure; %[output:4510eefd]
fig.Position(3:4) = [900 300];  % width height %[output:4510eefd]
SignalTool2.plotLookupTable1D(data_table.X, data_table.Y, InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:4510eefd]
